{!REQUIRESCRIPT("/soap/ajax/24.0/connection.js")} 

var isFlagChecked = '{!Case.IME_SC_Customer_At_Risk__c}'; 

var atRiskStatus = '{!Case.IME_SC_Customer_At_Risk_Status__c}'; 
var arrCase = []; 
var errors = []; 
var Case_New = new sforce.SObject("Case"); 
var url = parent.location.href; 
var Id_str =  '{!Case.Id}';

var assignment_qry = "select id from AssignmentRule where SobjectType = 'Case' and Active = true limit 1";
var Assignment_Qry_Result = sforce.connection.query(assignment_qry);


var qry = "select Id,name from RecordType where Name ='IM Employees Support Case' and SobjectType = 'Case'";
var result = [] ;
result =  sforce.connection.retrieve("IME_SC_Customer_At_Risk__c,ContactId,IME_SC_Customer_AccountId__c", "Case",  ['{!Case.Id}']);



var  rt = sforce.connection.query(qry);
var res = rt.getArray("records");

var recordtypeId = res[0].Id;

if(isFlagChecked == 1) 
{ 
     alert('{!$Label.IME_SC_At_Risk_Assessment_alert}');
} 
else 
{ 

if(atRiskStatus == "At Risk" || atRiskStatus == "Notified" || atRiskStatus == "Terminated" || atRiskStatus == "Exit in Progress") 
{ 


var iChoice = confirm('{!$Label.IME_SC_Risk_assessment_confirm}');
      if(iChoice) 
       { 

    if(result[0].ContactId == null )
    {
          alert('{!$Label.IME_SC_Contact_Not_Present}');
    }

         else
         {
            CreateNewCase(recordtypeId);

            result[0].IME_SC_Customer_At_Risk__c = true;

           var error = sforce.connection.update(result);
          if(error && error.length)
          {
                var numFailed = 0; 
               var numSucceeded = 0; 
                var errors = [];

               for (var i = 0; i < error.length; i++)
               {
                                  var res= error[i];

                         if(res && res.success == 'true')
                         {
                                numSucceeded++;
                         }
                         else
                         {
                                   var es = res.getArray("errors");

                                   if(es.length > 0)
                                   {
                                           errors.push(es[0].message); 
                                   }

                                   numFailed++; 

                         }


               }

               if (numFailed > 0)
              { 
                   alert("Failed: " + numFailed + "\nSucceeded: " + numSucceeded + " \n Due to: " + errors.join("\n")); 
              }
            else 
             { 

                 var str_Query_NewCase =  "select CaseNumber from Case where ParentId ='" + Id_str + "'";

                 var CaseNum;
                 CaseNum = sforce.connection.query(str_Query_NewCase);

                 var records = CaseNum.getArray("records");
                 if (records.length > 0)
                 {
                      var id = records[0].CaseNumber;

                       alert('New case#  ' + id + ' {!$Label.IME_SC_NEW_CASE}');
                }

                 window.location.reload();

              }
       }

   }

      }

     else
      {
            // parent.location.href = url; 
      }


}

else if(atRiskStatus == "Not At Risk" || atRiskStatus == "Salvaged" || atRiskStatus == "Retained" || atRiskStatus == "Unknown") 
{ 

                if(result[0].ContactId == null )
               {
                     alert('{!$Label.IME_SC_Contact_Not_Present}');
               }

               else
              {

               CreateNewCase(recordtypeId);
               result[0].IME_SC_Customer_At_Risk__c = true;
               sforce.connection.update(result);


                var str_Query_NewCase =  "select CaseNumber from Case where ParentId ='" + Id_str + "'";

                 var CaseNum;
                 CaseNum = sforce.connection.query(str_Query_NewCase);

                 var records = CaseNum.getArray("records");
                 if (records.length > 0)
                 {
                      var id = records[0].CaseNumber;

                       alert('New case# ' + id + ' {!$Label.IME_SC_NEW_CASE}');
                }

                 window.location.reload();

               }
}

else
{

        if(result[0].IME_SC_Customer_AccountId__c == null)
       {

                   alert('{!$Label.IME_SC_Cust_Acc_Not_Present}');
       }   

       else
       {      
           alert('{!$Label.IME_SC_At_Risk_Assessment_alert2}');
       }
}




}




function CreateNewCase(recordtypeId)
{
              var Case_New = new sforce.SObject("Case"); 
              Case_New.Origin = "Internal"; 
              Case_New.Status = "New";
              Case_New.ContactId = '{!Case.ContactId}';
             Case_New.RecordTypeId  =  recordtypeId;
             Case_New.Related_To__c = "Customer Account/Client Code"; 
              Case_New.Issue__c = "Request at Risk Assessment"; 
              Case_New.ParentId =  '{!Case.Id}';
               Case_New.IM_Division__c = '{!Case.IM_Division__c}';
               Case_New.IME_SC_Country__c = '{!Case.IME_SC_Country__c}';
              Case_New.Country__c = '{!Case.IME_SC_Country__c}';
               Case_New.Priority = "Medium" ;
               Case_New.AccountId = '{!Case.AccountId}';
               Case_New.IME_SC_Customer_AccountId__c = '{!Case.IME_SC_Customer_AccountIdId__c}';  
               Case_New.Customer_ID__c = '{!Case.IME_SC_Customer_AccountIdId__c}';  
               Case_New.Subject =  '{!$Label.IME_SC_Label_RetentionCaseSubject}';   
               Case_New.Description = '{!$Label.IME_SC_Label_RetentionCaseDescription}';

                   sforce.connection.assignmentRuleHeader = {} ;  
                  sforce.connection.assignmentRuleHeader.useDefaultRule = "true";  
                 //sforce.connection.EmailHeader.triggerUserEmail = true;
                  sforce.connection.emailHeader =  { triggerUserEmail : true};
                arrCase.push(Case_New); 

                var result_Case = sforce.connection.create(arrCase);

              if(result_Case && result_Case.length)
              {
                var numFailed = 0; 
               var numSucceeded = 0; 
                var errors = [];

               for (var i = 0; i < result_Case.length; i++)
               {
                        var res= result_Case[i];

                         if(res && res.success == 'true')
                         {
                                numSucceeded++;
                         }
                         else
                         {
                                   var es = res.getArray("errors");

                                   if(es.length > 0)
                                   {
                                           errors.push(es[0].message); 
                                   }

                                   numFailed++; 

                         }


               }

               if (numFailed > 0)
              { 
                   alert("Failed: " + numFailed + "\nSucceeded: " + numSucceeded + " \n Due to: " + errors.join("\n")); 
              }
            else 
             { 
                     // alert('Successful');
              }

         }

}
